import fcntl
import os
from pathlib import Path

def atomic_replace(path: Path, old: str, new: str, expected: int = 1) -> None:
    lock_path = Path('/tmp') / f'{path.name}.issue1497.lock'
    with lock_path.open('w', encoding='utf-8') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        text = path.read_text(encoding='utf-8')
        count = text.count(old)
        if count != expected:
            raise SystemExit(f'{path}: expected {expected} occurrence(s), found {count}')
        updated = text.replace(old, new, expected)
        temporary = path.with_suffix(path.suffix + '.issue1497.tmp')
        temporary.write_text(updated, encoding='utf-8')
        os.replace(temporary, path)

